#Увести координати кінців відрізка. Обчислити довжину цього відрізка.
#data:image/png;base64,
x1 = int(input("Введіть координату х початку відрізка: "))
y1 = int(input("Введіть координату y початку відрізка: "))
x2 = int(input("Введіть координату х кінця відрізка: "))
y2 = int(input("Введіть координату y кінця відрізка: "))
operation = (x2 - x1) ** 2 + (y2 - y1) ** 2
print(f"Довжина відрізка: {operation ** 0.5}")